// Shared St.Icon property resolver.
//
// Results cross the D-Bus boundary as plain strings, but `GIcon.to_string()`
// returns a file path (or file:// URI) for GFileIcon-based icons — e.g.
// games/exe launchers generated by Bottles store their icon as a PNG path.
// Feeding such a path to `St.Icon.icon_name` makes St look it up as a themed
// icon and fall back to a generic page glyph. Rebuild a GFileIcon for paths so
// St paints the actual image, and keep themed icon names untouched.

import Gio from 'gi://Gio';

export const FALLBACK_ICON = 'application-x-executable-symbolic';

function isPathIcon(value) {
  return value.startsWith('/') || value.startsWith('file://');
}

function fileIconFor(value) {
  try {
    const file = value.startsWith('file://')
      ? Gio.File.new_for_uri(value)
      : Gio.File.new_for_path(value);
    if (!file.query_exists(null))
      return null;
    return new Gio.FileIcon({ file });
  } catch {
    return null;
  }
}

/**
 * Turn a result's `icon` value into St.Icon constructor properties.
 *
 * @param {string|object|null|undefined} icon
 * @param {string} [fallback]
 * @returns {{icon_name?: string, gicon?: object}}
 */
export function iconProperties(icon, fallback = FALLBACK_ICON) {
  if (typeof icon === 'string') {
    const value = icon.trim();
    if (value === '')
      return { icon_name: fallback };

    if (isPathIcon(value)) {
      const gicon = fileIconFor(value);
      return gicon ? { gicon } : { icon_name: fallback };
    }

    return { icon_name: value };
  }

  if (icon)
    return { gicon: icon };

  return { icon_name: fallback };
}

export default {
  iconProperties,
  FALLBACK_ICON,
};
